   588	  // Check for synthetic classes that hold switchmaps and assert fields
   589	  private static boolean shouldInitEarly(ClassNode node) {
   590	    if (node.classStruct.hasModifier(CodeConstants.ACC_SYNTHETIC)) {
   591	      if (node.classStruct.getMethods().size() == 1 && node.classStruct.getMethods().get(0).getName().equals(CodeConstants.CLINIT_NAME)) {
   592	        return node.classStruct.getFields().stream()
   593	          .allMatch( stField -> (stField.getDescriptor().equals("[I") || stField.getDescriptor().equals("Z")) && stField.hasModifier(SwitchHelper.STATIC_FINAL_SYNTHETIC));
   594	      }
   595	    }
   596	    return false;
   597	  }
