  1969	  private static boolean searchForMethod(StructClass cl, String name, MethodDescriptor md, boolean search) {
  1970	    // Didn't find the class or the library containing the class wasn't loaded, can't search
  1971	    if (cl == null) {
  1972	      return false;
  1973	    }
  1974	
  1975	    VBStyleCollection<StructMethod, String> methods = cl.getMethods();
  1976	
  1977	    if (search) {
  1978	      // If we're allowed to search, iterate through the methods and try to find matches
  1979	      for (StructMethod method : methods) {
  1980	        // Match against name, descriptor, and whether or not the found method is static.
  1981	        // TODO: We are not handling generics or superclass parameters and return types
  1982	        if (md.equals(MethodDescriptor.parseDescriptor(method.getDescriptor())) && name.equals(method.getName()) && !method.hasModifier(CodeConstants.ACC_STATIC)) {
  1983	          return true;
  1984	        }
  1985	      }
  1986	    }
  1987	
  1988	    // If we have a superclass that's not Object, search that as well
  1989	    if (cl.superClass != null) {
  1990	      StructClass superClass = DecompilerContext.getStructContext().getClass((String)cl.superClass.value);
  1991	
  1992	      boolean foundInSuperClass = searchForMethod(superClass, name, md, true);
  1993	
  1994	      if (foundInSuperClass) {
  1995	        return true;
  1996	      }
  1997	    }
  1998	
  1999	    // Search all of the interfaces implemented by this class for the method
  2000	    for (String ifaceName : cl.getInterfaceNames()) {
  2001	      StructClass iface = DecompilerContext.getStructContext().getClass(ifaceName);
  2002	
  2003	      boolean foundInIface = searchForMethod(iface, name, md, true);
  2004	
  2005	      if (foundInIface) {
  2006	        return true;
  2007	      }
  2008	    }
  2009	
  2010	    // We didn't manage to find anything, return
  2011	    return false;
