    32	  public static MethodDescriptor parseDescriptor(String descriptor) {
    33	    int parenth = descriptor.lastIndexOf(')');
    34	    if (descriptor.length() < 2 || parenth < 0 || descriptor.charAt(0) != '(') {
    35	      throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
    36	    }
    37	
    38	    VarType[] params;
    39	
    40	    if (parenth > 1) {
    41	      String parameters = descriptor.substring(1, parenth);
    42	      List<String> lst = new ArrayList<>();
    43	
    44	      int indexFrom = -1, ind, len = parameters.length(), index = 0;
    45	      while (index < len) {
    46	        switch (parameters.charAt(index)) {
    47	          case '[':
    48	            if (indexFrom < 0) {
    49	              indexFrom = index;
    50	            }
    51	            break;
    52	          case 'L':
    53	            ind = parameters.indexOf(";", index);
    54	            lst.add(parameters.substring(indexFrom < 0 ? index : indexFrom, ind + 1));
    55	            index = ind;
    56	            indexFrom = -1;
    57	            break;
    58	          default:
    59	            lst.add(parameters.substring(indexFrom < 0 ? index : indexFrom, index + 1));
    60	            indexFrom = -1;
    61	        }
    62	        index++;
    63	      }
    64	
    65	      params = new VarType[lst.size()];
    66	      for (int i = 0; i < lst.size(); i++) {
    67	        params[i] = new VarType(lst.get(i));
    68	      }
    69	    }
    70	    else {
    71	      params = VarType.EMPTY_ARRAY;
    72	    }
    73	
    74	    VarType ret = new VarType(descriptor.substring(parenth + 1));
    75	
    76	    return new MethodDescriptor(params, ret, descriptor);
    77	  }
