    StructGeneralAttribute attribute = StructGeneralAttribute.createAttribute(Key.of(name));
    int length = in.readInt();
    if (attribute == null) {
      in.discard(length);
    }
    else {
      attribute.initContent(in, pool, getVersion());
    }
