  @Override
  public void writeClass(ClassNode node, TextBuffer buffer, int indent) {
    if (node.type == ClassNode.Type.ROOT && referenceAwareRetention == null &&
      DecompilerContext.getOption(IFernflowerPreferences.REFERENCE_AWARE_SYNTHETIC_RETENTION)) {
      writeReferenceAwareClass(node, buffer, indent);
    } else {
      writeClassInternal(node, buffer, indent);
    }
  }

  private void writeReferenceAwareClass(ClassNode node, TextBuffer buffer, int indent) {
    ReferenceAwareSyntheticRetention previous = DecompilerContext.getContextProperty(REFERENCE_AWARE_RETENTION);
    ReferenceAwareSyntheticRetention retention = new ReferenceAwareSyntheticRetention(node);
    referenceAwareRetention = retention;
    DecompilerContext.setProperty(REFERENCE_AWARE_RETENTION, retention);

    try {
      boolean changed;
      do {
        TextBuffer candidate = new TextBuffer(ClassesProcessor.AVERAGE_CLASS_SIZE);
        changed = false;

        resetAnnotationState(node);
        writeClassInternal(node, candidate, indent);
        candidate.reformat();
        retention.findOmittedCandidates(candidate);

        for (MemberKey member : referencesToOmittedMembers(candidate)) {
          if (retention.retained.add(member)) {
            changed = true;
          }
        }
      } while (changed);

      resetAnnotationState(node);
      writeClassInternal(node, buffer, indent);
    } finally {
      referenceAwareRetention = previous;
      DecompilerContext.setProperty(REFERENCE_AWARE_RETENTION, previous);
    }
  }

  private Set<MemberKey> referencesToOmittedMembers(TextBuffer buffer) {
    Set<MemberKey> references = new HashSet<>();

    for (TextToken token : buffer.getTokens()) {
      if (token.isDeclaration()) {
        continue;
      }

      MemberKey member = memberFromToken(token);

      if (member != null && referenceAwareRetention.isOmittedCandidate(member)) {
        references.add(member);
      }
    }

    return references;
  }

  private static MemberKey memberFromToken(TextToken token) {
    if (token instanceof FieldTextToken field) {
      return MemberKey.field(field.className, field.name, field.descriptor.descriptorString);
    } else if (token instanceof MethodTextToken method) {
      return MemberKey.method(method.className, method.name, method.descriptor.toString());
    } else if (token instanceof ClassTextToken clazz) {
      return MemberKey.clazz(clazz.qualifiedName);
    }

    return null;
  }

  private static void resetAnnotationState(ClassNode node) {
    if (node.type != ClassNode.Type.LAMBDA) {
      resetAnnotationState(node.classStruct);
      for (StructField field : node.classStruct.getFields()) {
        resetAnnotationState(field);
      }
      for (StructMethod method : node.classStruct.getMethods()) {
        resetAnnotationState(method);
      }
      List<StructRecordComponent> components = node.classStruct.getRecordComponents();
      if (components != null) {
        for (StructRecordComponent component : components) {
          resetAnnotationState(component);
        }
      }
    }

    for (ClassNode inner : node.nested) {
      resetAnnotationState(inner);
    }
  }

  private static void resetAnnotationState(StructMember member) {
    for (Key<?> key : ANNOTATION_ATTRIBUTES) {
      StructAnnotationAttribute attribute = member.getAttribute((Key<StructAnnotationAttribute>)key);
      if (attribute != null) {
        for (AnnotationExprent annotation : attribute.getAnnotations()) {
          resetAnnotationState(annotation);
        }
      }
    }

    for (Key<?> key : TYPE_ANNOTATION_ATTRIBUTES) {
      StructTypeAnnotationAttribute attribute = member.getAttribute((Key<StructTypeAnnotationAttribute>)key);
      if (attribute != null) {
        for (TypeAnnotation annotation : attribute.getAnnotations()) {
          resetAnnotationState(annotation.getAnnotation());
        }
      }
    }

    for (Key<?> key : PARAMETER_ANNOTATION_ATTRIBUTES) {
      StructAnnotationParameterAttribute attribute = member.getAttribute((Key<StructAnnotationParameterAttribute>)key);
      if (attribute != null) {
        for (List<AnnotationExprent> annotations : attribute.getParamAnnotations()) {
          for (AnnotationExprent annotation : annotations) {
            resetAnnotationState(annotation);
          }
        }
      }
    }
  }

  private static void resetAnnotationState(AnnotationExprent annotation) {
    annotation.setDidWriteAlready(false);
    for (Exprent exprent : annotation.getAllExprents(true)) {
      if (exprent instanceof AnnotationExprent nested) {
        nested.setDidWriteAlready(false);
      }
    }
  }

  private void writeClassInternal(ClassNode node, TextBuffer buffer, int indent) {
    ClassNode outerNode = (ClassNode)DecompilerContext.getContextProperty(DecompilerContext.CURRENT_CLASS_NODE);
    DecompilerContext.setProperty(DecompilerContext.CURRENT_CLASS_NODE, node);

    try {
      // last minute processing
      boolean ok = true;
      if (referenceAwareRetention == null || referenceAwareRetention.processedNodes.add(node)) {
        ok = invokeProcessors(buffer, node);
      }

      if (!ok) {
        return;
      }

      ClassWrapper wrapper = node.getWrapper();
      StructClass cl = wrapper.getClassStruct();

      DecompilerContext.getLogger().startWriteClass(cl.qualifiedName);

      if (DecompilerContext.getOption(IFernflowerPreferences.SOURCE_FILE_COMMENTS)) {
        StructSourceFileAttribute sourceFileAttr = node.classStruct
          .getAttribute(StructGeneralAttribute.ATTRIBUTE_SOURCE_FILE);

        if (sourceFileAttr != null) {
          ConstantPool pool = node.classStruct.getPool();
          String sourceFile = sourceFileAttr.getSourceFile(pool);

          buffer
            .appendIndent(indent)
            .append("// $VF: Compiled from " + sourceFile)
            .appendLineSeparator();
        }
      }

      // write class definition
      writeClassDefinition(node, buffer, indent);

      final AtomicBoolean hasContent = new AtomicBoolean(false);
      // writeClassDefinition will skip adding a trailing newline for anonymous classes.
      // This allows us to only add it if we end up writing any content for the class, so something
      // like `new Object() {}` will not have a newline in between `{` and `}`.
      // The runnable should be executed immediately before writing any anonymous class content to the buffer.
      // hasContent also fills a similar purpose, determining whether elements need an extra newline prepended due to previous content being written.
      final Runnable haveContent = () -> {
        if (!hasContent.get() && node.type == ClassNode.Type.ANONYMOUS) {
          buffer.appendLineSeparator();
        }
        hasContent.set(true);
      };

      String methodToDecompile = (String) DecompilerContext.getProperty(IFernflowerPreferences.METHOD_TO_DECOMPILE);

      // fields
      if (methodToDecompile.isEmpty()) {
        List<StructRecordComponent> components = cl.getRecordComponents();

        List<StructField> enumFields = new ArrayList<>();
        List<StructField> nonEnumFields = new ArrayList<>();

        for (StructField fd : cl.getFields()) {
          boolean isEnum = fd.hasModifier(CodeConstants.ACC_ENUM) && DecompilerContext.getOption(IFernflowerPreferences.DECOMPILE_ENUM);
          if (isEnum) {
            enumFields.add(fd);
          } else {
            nonEnumFields.add(fd);
          }
        }

        boolean enums = false;
        for (StructField fd : enumFields) {
          if (enums) {
            buffer.append(',').appendLineSeparator();
          }
          enums = true;

          haveContent.run();
          writeField(buffer, indent, fd, wrapper);
        }

        if (enums) {
          buffer.append(';').appendLineSeparator();
        }

        for (StructField fd : nonEnumFields) {
          boolean hide = isFieldHidden(fd, wrapper);
          if (hide && isRetained(MemberKey.field(cl.qualifiedName, fd.getName(), fd.getDescriptor()))) {
            hide = false;
          }
          if (hide) continue;

          if (components != null && fd.getAccessFlags() == (CodeConstants.ACC_FINAL | CodeConstants.ACC_PRIVATE) &&
            components.stream().anyMatch(c -> c.getName().equals(fd.getName()) && c.getDescriptor().equals(fd.getDescriptor()))) {
            // Record component field: skip it
            continue;
          }

          if (enums) {
            // Add an extra line break between enums and non-enum fields
            buffer.appendLineSeparator();
            enums = false;
          }

          haveContent.run();
          writeField(buffer, indent, fd, wrapper);
        }
      }

      // methods
      VBStyleCollection<StructMethod, String> methods = cl.getMethods();
      for (int i = 0; i < methods.size(); i++) {
        StructMethod mt = methods.get(i);
        boolean hide;
        if (methodToDecompile.isEmpty() || (node.type != ClassNode.Type.ROOT && node.type != ClassNode.Type.MEMBER)) {
          hide = isMethodHidden(mt, wrapper);
        } else {
          hide = !methodToDecompile.equals(cl.qualifiedName + "." + mt.getName() + mt.getDescriptor()) &&
                 (node.type != ClassNode.Type.ROOT || !methodToDecompile.equals(mt.getName() + mt.getDescriptor()));
        }
        if (hide && isRetained(MemberKey.method(cl.qualifiedName, mt.getName(), mt.getDescriptor()))) {
          hide = false;
        }
        if (hide) continue;

        TextBuffer methodBuffer = new TextBuffer();
        boolean methodSkipped = !writeMethod(node, mt, i, methodBuffer, indent + 1);
        if (!methodSkipped) {
          if (hasContent.get()) {
            buffer.appendLineSeparator();
          }
          haveContent.run();
          buffer.append(methodBuffer);
        }
      }

      // member classes
      for (ClassNode inner : node.nested) {
        if (inner.type == ClassNode.Type.MEMBER) {
          StructClass innerCl = inner.classStruct;
          boolean hide;
          if (methodToDecompile.isEmpty()) {
            hide = isMemberClassHidden(inner, wrapper);
          } else {
            hide = !methodToDecompile.startsWith(innerCl.qualifiedName + ".");
          }
          if (hide && isRetained(MemberKey.clazz(innerCl.qualifiedName))) {
            hide = false;
          }
          if (hide) continue;

          if (hasContent.get()) {
            buffer.appendLineSeparator();
          }
          TextBuffer clsBuffer = new TextBuffer();
          writeClassInternal(inner, clsBuffer, indent + 1);
          haveContent.run();
          buffer.append(clsBuffer);
        }
      }

      if (hasContent.get() || node.type != ClassNode.Type.ANONYMOUS) {
        // Skip indent for anonymous classes with no content, since we also skipped the newline in the cls definition
        buffer.appendIndent(indent);
      }
      buffer.append('}');

      if (node.type != ClassNode.Type.ANONYMOUS) {
        buffer.appendLineSeparator();
      }
    }
    finally {
      DecompilerContext.setProperty(DecompilerContext.CURRENT_CLASS_NODE, outerNode);
    }

    DecompilerContext.getLogger().endWriteClass();
  }

  private boolean isRetained(MemberKey member) {
    return referenceAwareRetention != null && referenceAwareRetention.retained.contains(member);
  }

  private static boolean isFieldHidden(StructField field, ClassWrapper wrapper) {
    return field.isSynthetic() && DecompilerContext.getOption(IFernflowerPreferences.REMOVE_SYNTHETIC) ||
      wrapper.getHiddenMembers().contains(InterpreterUtil.makeUniqueKey(field.getName(), field.getDescriptor()));
  }

  private static boolean isMethodHidden(StructMethod method, ClassWrapper wrapper) {
    return method.isSynthetic() && DecompilerContext.getOption(IFernflowerPreferences.REMOVE_SYNTHETIC) ||
      method.hasModifier(CodeConstants.ACC_BRIDGE) && DecompilerContext.getOption(IFernflowerPreferences.REMOVE_BRIDGE) ||
      wrapper.getHiddenMembers().contains(InterpreterUtil.makeUniqueKey(method.getName(), method.getDescriptor()));
  }

  private static boolean isMemberClassHidden(ClassNode inner, ClassWrapper wrapper) {
    boolean isSynthetic = (inner.access & CodeConstants.ACC_SYNTHETIC) != 0 || inner.classStruct.isSynthetic();
    return isSynthetic && DecompilerContext.getOption(IFernflowerPreferences.REMOVE_SYNTHETIC) ||
      wrapper.getHiddenMembers().contains(inner.classStruct.qualifiedName);
  }

  public static void packageInfoToJava(StructClass cl, TextBuffer buffer) {
    appendAnnotations(buffer, 0, cl, -1);

    int index = cl.qualifiedName.lastIndexOf('/');
    String packageName = cl.qualifiedName.substring(0, index).replace('/', '.');
    buffer.append("package ").append(packageName).append(';').appendLineSeparator().appendLineSeparator();
  }

  public static void moduleInfoToJava(StructClass cl, TextBuffer buffer) {
    appendAnnotations(buffer, 0, cl, -1);

    StructModuleAttribute moduleAttribute = cl.getAttribute(StructGeneralAttribute.ATTRIBUTE_MODULE);

    if ((moduleAttribute.moduleFlags & CodeConstants.ACC_OPEN) != 0) {
      buffer.append("open ");
    }

    buffer.append("module ").append(moduleAttribute.moduleName).append(" {").appendLineSeparator();
  }

  public static void appendTypeParameters(TextBuffer buffer, List<String> parameters, List<List<VarType>> bounds) {
    buffer.append('<');

    for (int i = 0; i < parameters.size(); i++) {
      if (i > 0) {
        buffer.append(", ");
      }

      buffer.append(parameters.get(i));

      List<VarType> parameterBounds = bounds.get(i);
      if (parameterBounds.size() > 1 || !"java/lang/Object".equals(parameterBounds.get(0).value)) {
        buffer.append(" extends ");
        buffer.appendCastTypeName(parameterBounds.get(0));
        for (int j = 1; j < parameterBounds.size(); j++) {
          buffer.append(" & ");
          buffer.appendCastTypeName(parameterBounds.get(j));
        }
      }
    }

    buffer.append('>');
  }

  private static void appendFQClassNames(TextBuffer buffer, List<String> names) {
    for (int i = 0; i < names.size(); i++) {
      String name = names.get(i);
      buffer.appendIndent(2).append(name);
      if (i < names.size() - 1) {
        buffer.append(',').appendLineSeparator();
      }
    }
  }

  private final class ReferenceAwareSyntheticRetention {
    private final Set<MemberKey> potential = new HashSet<>();
    private final Set<MemberKey> candidates = new HashSet<>();
    private final Set<MemberKey> retained = new HashSet<>();
    private final Set<ClassNode> processedNodes = Collections.newSetFromMap(new IdentityHashMap<>());
    private boolean candidatesDetermined;

    private ReferenceAwareSyntheticRetention(ClassNode root) {
      collectPotentialMembers(root);
    }

    private boolean isOmittedCandidate(MemberKey member) {
      return candidates.contains(member) && !retained.contains(member);
    }

    private void findOmittedCandidates(TextBuffer buffer) {
      if (candidatesDetermined) {
        return;
      }

      Set<MemberKey> declared = new HashSet<>();
      for (TextToken token : buffer.getTokens()) {
        if (token.isDeclaration()) {
          MemberKey member = memberFromToken(token);
          if (member != null) {
            declared.add(member);
          }
        }
      }

      candidates.addAll(potential);
      candidates.removeAll(declared);
      candidatesDetermined = true;
    }

    private void collectPotentialMembers(ClassNode node) {
      // Lambda nodes reuse their enclosing class's StructClass and wrapper. They are
      // representation nodes, not declarations in their own right.
      if (node.type != ClassNode.Type.LAMBDA) {
        for (StructField field : node.classStruct.getFields()) {
          if (field.isSynthetic()) {
            potential.add(MemberKey.field(node.classStruct.qualifiedName, field.getName(), field.getDescriptor()));
          }
        }

        for (StructMethod method : node.classStruct.getMethods()) {
          if (method.isSynthetic() || method.hasModifier(CodeConstants.ACC_BRIDGE)) {
            potential.add(MemberKey.method(node.classStruct.qualifiedName, method.getName(), method.getDescriptor()));
          }
        }

        for (ClassNode inner : node.nested) {
          if (inner.type == ClassNode.Type.MEMBER &&
            ((inner.access & CodeConstants.ACC_SYNTHETIC) != 0 || inner.classStruct.isSynthetic())) {
            potential.add(MemberKey.clazz(inner.classStruct.qualifiedName));
          }
        }
      }

      for (ClassNode inner : node.nested) {
        collectPotentialMembers(inner);
      }
    }
  }

  private record MemberKey(Kind kind, String className, String name, String descriptor) {
    private enum Kind { FIELD, METHOD, CLASS }

    private static MemberKey field(String className, String name, String descriptor) {
      return new MemberKey(Kind.FIELD, className, name, descriptor);
    }

    private static MemberKey method(String className, String name, String descriptor) {
      return new MemberKey(Kind.METHOD, className, name, descriptor);
    }

    private static MemberKey clazz(String className) {
      return new MemberKey(Kind.CLASS, className, null, null);
    }
  }
